    '04-29': [proper('Saint Catherine of Siena, Virgin and Doctor, Co-Patron of Europe', '유럽 공동 수호자 시에나의 성녀 가타리나 동정 학자 축일', 'feast')],
    '06-09': [proper('Saint Columba (Colum Cille), Abbot', '성 콜룸바 아빠스 축일', 'feast')],
